/**
 * Roles that occupy a seat on the plan's `seats` quota. A `viewer` is free.
 * Every seat count and seat check goes through this, never a role literal.
 */
export function isBillableRole(role: Role): boolean {
  return role !== "viewer";
}

export const BILLABLE_ROLES: readonly Role[] = ROLES.filter(isBillableRole);

export type MemberStatus = "active" | "invited" | "suspended";

/** True when a member with this role and status holds a seat. */
export function occupiesSeat(role: Role, status: MemberStatus): boolean {
  return status === "active" && isBillableRole(role);
}

