            Remove member
          </Button>
        </DialogFooter>
      }
    >
      <p className="text-sm">
        {member.user.email} is currently a <RoleBadge role={member.role} /> in
        this organization. Removing them frees one seat.
      </p>
    </Dialog>
  );
}

/**
 * Member management with invite and role controls.
 *
 * Owner D. The seat check is computed here and handed to both the invite form
 * (which disables itself when full) and the banner — one `LimitCheck`, two
 * consumers, so they cannot disagree.
 *
 * Must call (do not reimplement): can, getPlanLimits
 */

import { notFound } from "next/navigation";
import Link from "next/link";
import type { Metadata } from "next";
import { inviteMemberAction } from "@/actions/members/invite-member";
import { removeMemberAction } from "@/actions/members/remove-member";
import { updateMemberRoleAction } from "@/actions/members/update-member-role";
import { PENDING_MEMBER_ID } from "@/actions/_lib/permission-resources";
import { InviteMemberForm } from "@/components/domain/member/invite-member-form";
import { MemberTable } from "@/components/domain/member/member-table";
import { SeatLimitBanner } from "@/components/domain/billing/seat-limit-banner";
import { getPlanLimits } from "@/config/plan-limits";
import { can } from "@/lib/permissions";
import { searchParamsPaginationSchema } from "@/schemas/pagination";
import { checkLimit } from "@/server/services/billing-service";
import { listMembers } from "@/server/services/member-service";
import type { LimitCheck } from "@/types/billing";
import type { MemberId } from "@/types/common";
import type { Role } from "@/types/member";
import { loadTenantContext } from "../../_lib/tenant-context";

type PageParams = { orgSlug: string };

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "Members",
};

export default async function Page(props: {
  params: Promise<PageParams>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  // Next.js 16: params and searchParams are Promises and MUST be awaited.
  const { orgSlug } = await props.params;
  const search = await props.searchParams;

  const { org, actor } = await loadTenantContext(orgSlug);

  const mayRead = can(actor, "member:read", {
    kind: "member",
    orgId: org.id,
    memberId: PENDING_MEMBER_ID,
    targetUserId: actor.userId,
    targetRole: actor.role,
  });
  if (!mayRead) {
    notFound();
  }

  const mayInvite = can(actor, "member:invite", {
    kind: "member",
    orgId: org.id,
    memberId: PENDING_MEMBER_ID,
    targetUserId: actor.userId,
    targetRole: "member",
  });

  const pagination = searchParamsPaginationSchema.parse(search);

  const [members, seats] = await Promise.all([
    listMembers(actor, {
      orgId: org.id,
      limit: pagination.perPage,
      cursor: pagination.cursor ?? null,
    }),
    checkLimit(org.id, "seats"),
  ]);

  // The plan's ceiling is shown next to the live check so the page explains the
  // number rather than just enforcing it.
  const limits = getPlanLimits(org.plan);

  async function changeRole(memberId: MemberId, role: Role): Promise<void> {
    "use server";
    await updateMemberRoleAction({ orgId: org.id, memberId, role });
  }

  async function remove(memberId: MemberId): Promise<void> {
    "use server";
    await removeMemberAction({ orgId: org.id, memberId });
  }

  return (
    <div className="space-y-8">
      <header className="flex items-baseline justify-between">
        <div>
          <h1 className="text-xl font-semibold tracking-tight">Members</h1>
          <p className="mt-1 text-sm text-slate-600">
            {members.total} of {limits.seats} seats used on the {org.plan} plan.
          </p>
        </div>
        <Link
          href={`/${orgSlug}/settings/members/invitations`}
          className="text-sm text-indigo-600"
        >
          Pending invitations
        </Link>
      </header>

      <SeatLimitBanner check={seats satisfies LimitCheck} orgSlug={orgSlug} actor={actor} />

      {mayInvite ? (
        <InviteMemberForm
          orgId={org.id}
          actor={actor}
          seatCheck={seats}
          onSubmit={inviteMemberAction}
        />
      ) : null}

      <MemberTable
        members={members.items}
        actor={actor}
        onRoleChange={changeRole}
        onRemove={remove}
      />
    </div>
  );
}

/**
 * Pending invitations.
 *
 * Owner D. Read-only listing plus revoke. `InvitationService` exposes the
 * lifecycle verbs but no listing, so the page reads
 * `listPendingInvitations()` from the repository directly — the query is
 * already org-scoped and there is no rule for a service to add on top of it.
 *
 * Must call (do not reimplement): can
 */

import { notFound } from "next/navigation";
import type { Metadata } from "next";
import { PENDING_MEMBER_ID } from "@/actions/_lib/permission-resources";
import { InvitationList } from "@/components/domain/member/invitation-list";
import { EmptyState } from "@/components/ui/empty-state";
import { can } from "@/lib/permissions";
import { listPendingInvitations } from "@/server/repositories/invitation-repository";
import { revokeInvitation } from "@/server/services/invitation-service";
import type { InvitationId } from "@/types/common";
import { loadTenantContext } from "../../../_lib/tenant-context";

type PageParams = { orgSlug: string };

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "Pending invitations",
};

export default async function Page(props: {
  params: Promise<PageParams>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  // Next.js 16: params and searchParams are Promises and MUST be awaited.
  const { orgSlug } = await props.params;
  await props.searchParams;

  const { org, actor } = await loadTenantContext(orgSlug);

  const mayRead = can(actor, "member:read", {
    kind: "member",
    orgId: org.id,
    memberId: PENDING_MEMBER_ID,
    targetUserId: actor.userId,
    targetRole: actor.role,
  });
  if (!mayRead) {
    notFound();
  }

  const invitations = await listPendingInvitations(org.id);

  async function revoke(invitationId: InvitationId): Promise<void> {
    "use server";
    await revokeInvitation(actor, invitationId);
  }

  return (
    <div className="space-y-8">
      <header>
        <h1 className="text-xl font-semibold tracking-tight">
          Pending invitations
        </h1>
        <p className="mt-1 text-sm text-slate-600">
          Invitations that have been sent but not yet accepted. Each one still
          counts against the seat quota.
        </p>
      </header>

      {invitations.length === 0 ? (
        <EmptyState
          title="No invitations outstanding"
          description="Everybody who was invited has either joined or been revoked."
        />
      ) : (
        <InvitationList
          invitations={invitations}
          actor={actor}
          onRevoke={revoke}
        />
      )}
    </div>
  );
}

/**
 * The background job layer: the in-process queue, the scheduler's cadence and
 * the two jobs whose behaviour other layers depend on — the overdue scan that
 * feeds the notification fan-out, and the trial expiry that moves plans.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import {
  drain,
  enqueue,
  isSchedulerRunning,
  pendingCount,
  resetQueue,
  startScheduler,
  stopScheduler,
} from "@/server/jobs";
import { backoffMs } from "@/server/jobs/webhook-delivery-job";
import { shouldRunForOrg } from "@/server/jobs/digest-email-job";
import { runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import { runUsageRollupJob } from "@/server/jobs/usage-rollup-job";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as issueService from "@/server/services/issue-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
const detachers: Unsubscribe[] = [];

const PAST = "2026-01-01T00:00:00.000Z";
const NOW = new Date("2026-06-01T07:00:00.000Z");

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("jobs");
  await usageRepo.recomputeUsage(tenant.org.id);
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
  resetQueue();
  stopScheduler();
});

afterAll(() => {
  cleanup();
});

describe("the in-process queue", () => {
  it("is idempotent on the job id", () => {
    const job = {
      id: "usage-rollup:1",
      kind: "usage-rollup" as const,
      runAt: toIsoTimestamp(NOW),
      attempts: 0,
      payload: {},
    };

    enqueue(job);
    enqueue(job);

    expect(pendingCount()).toBe(1);
  });

  it("leaves jobs scheduled in the future alone", async () => {
    enqueue({
      id: "usage-rollup:future",
      kind: "usage-rollup",
      runAt: toIsoTimestamp(new Date(Date.now() + 3_600_000)),
      attempts: 0,
      payload: {},
    });

    await expect(drain()).resolves.toBe(0);
    expect(pendingCount()).toBe(1);
  });

  it("runs a due job and removes it", async () => {
    enqueue({
      id: "usage-rollup:due",
      kind: "usage-rollup",
      runAt: toIsoTimestamp(new Date(Date.now() - 1_000)),
      attempts: 0,
      payload: {},
    });

    await expect(drain()).resolves.toBe(1);
    expect(pendingCount()).toBe(0);
  });
});

describe("the scheduler", () => {
  it("reports whether it is running and stops cleanly", () => {
    expect(isSchedulerRunning()).toBe(false);
    startScheduler();
    expect(isSchedulerRunning()).toBe(true);
    stopScheduler();
    expect(isSchedulerRunning()).toBe(false);
  });
});

describe("the overdue scan", () => {
  it("emits issue.overdue for a past-due open issue, once", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Late already",
        assigneeId: tenant.userIds.member,
        dueAt: PAST,
      }),
    );

    const seen: string[] = [];
    detachers.push(
      subscribe("issue.overdue", (payload) => {
        seen.push(payload.issueId);
      }),
    );

    const result = await runOverdueIssueJob(NOW);

    expect(seen).toEqual([issue.id]);
    expect(result.kind).toBe("overdue-issues");
    expect(result.processed).toBe(1);
    expect(result.failed).toBe(0);
  });

  it("ignores an overdue issue once it is archived", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Late but archived",
        dueAt: PAST,
      }),
    );
    await issueService.archiveIssue(
      tenant.actors.member,
      tenant.org.id,
      issue.id,
    );

    const overdue = await issueRepo.listOverdueIssues(
      tenant.org.id,
      toIsoTimestamp(NOW),
    );

    expect(overdue.map((row) => row.id)).not.toContain(issue.id);
  });

  it("ignores an overdue issue once it is closed", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Late but done",
        dueAt: PAST,
      }),
    );
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      status: "done",
    });

    const overdue = await issueRepo.listOverdueIssues(
      tenant.org.id,
      toIsoTimestamp(NOW),
    );

    expect(overdue.map((row) => row.id)).not.toContain(issue.id);
  });
});

describe("the usage rollup", () => {
  it("recounts the tenant's live rows", async () => {
    const result = await runUsageRollupJob(NOW);
    expect(result.processed).toBeGreaterThan(0);

    const usage = await usageRepo.getUsage(tenant.org.id);
    const live = await issueRepo.listIssues({
      orgId: tenant.org.id,
      limit: 100,
      cursor: null,
    });

    expect(usage.issuesUsed).toBe(live.total);
    expect(usage.seatsUsed).toBe(4);
  });
});

describe("pure job helpers", () => {
  it("backs delivery attempts off exponentially, with a ceiling", () => {
    expect(backoffMs(0)).toBe(0);
    expect(backoffMs(1)).toBe(1_000);
    expect(backoffMs(2)).toBe(2_000);
    expect(backoffMs(3)).toBe(4_000);
    expect(backoffMs(30)).toBe(300_000);
  });

  it("runs the digest only during the org's configured UTC hour", () => {
    const org = {
      ...tenant.org,
      settings: { ...tenant.org.settings, digestHourUtc: 7 },
    };

    expect(shouldRunForOrg(org, NOW)).toBe(true);
    expect(
      shouldRunForOrg(org, new Date("2026-06-01T08:00:00.000Z")),
    ).toBe(false);
    expect(
      shouldRunForOrg({ ...org, archivedAt: toIsoTimestamp(NOW) }, NOW),
    ).toBe(false);
  });
});

/**
 * Plan-limit enforcement on the write paths.
 *
 * `PLAN_LIMITS` is the single source of the numbers and `wouldExceedLimit()`
 * the single comparison; these cases prove the services actually consult them
 * before writing, and that a pending invitation already holds its seat.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);
// The only double left in this suite. `@/lib/rate-limit` is real everywhere
// else, but these cases need to *choose* the verdict — the seat-quota refusal
// has to be provably about seats and not about a bucket the previous case
// happened to drain, and the throttling case needs a guaranteed denial.
vi.mock("@/lib/rate-limit", async () => (await import("./_support/doubles/misc")).rateLimitModule);

import { getPlanLimits } from "@/config/plan-limits";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as billingService from "@/server/services/billing-service";
import * as invitationService from "@/server/services/invitation-service";
import * as projectService from "@/server/services/project-service";
import * as usageService from "@/server/services/usage-service";
import { rateLimitState } from "./_support/doubles/misc";
import { createTenant, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";

let cleanup: () => void;
/** Free plan: 3 seats, 2 projects. The fixture seeds four members. */
let free: Tenant;
let growth: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  free = await createTenant("frugal", "free");
  growth = await createTenant("growing", "growth");
});

afterAll(() => {
  cleanup();
  rateLimitState.allowed = true;
});

describe("seat quota on invite", () => {
  it("rejects an invite once the plan's seats are taken", async () => {
    expect(getPlanLimits("free").seats).toBe(3);
    await expect(memberRepo.countActiveMembers(free.org.id)).resolves.toBe(4);

    await expect(
      invitationService.inviteMember(free.actors.owner, {
        orgId: free.org.id,
        email: "fifth@frugal.test",
        role: "member",
      }),
    ).rejects.toThrow(/seats/i);
  });

  it("writes no invitation row when the quota rejects the batch", async () => {
    await expect(
      invitationRepo.countPendingInvitations(free.org.id),
    ).resolves.toBe(0);
  });

  it("rejects a bulk invite as a whole rather than partially filling it", async () => {
    const limits = getPlanLimits("growth");
    expect(limits.seats).toBe(50);

    const invites = Array.from({ length: 49 }, (_, index) => ({
      email: `bulk-${index}@growing.test`,
      role: "member" as const,
    }));

    await expect(
      invitationService.inviteMembers(growth.actors.owner, {
        orgId: growth.org.id,
        invites,
      }),
